mapper.select:
SELECT 
FROM diary_pages
WHERE id = #{pageId}
  AND diary_id = #{diaryId}

SELECT MAX(page_order)
FROM diary_pages
WHERE diary_id = #{diaryId}

mapper.update:
UPDATE diary_pages
SET content = #{content},
    updated_at = NOW()
WHERE id = #{pageId}
  AND diary_id = #{diaryId}

UPDATE diary_pages
SET page_order = page_order - 1
WHERE diary_id = #{diaryId}
  AND page_order > #{pageOrder}
ORDER BY page_order ASC

mapper.delete:
DELETE FROM diary_pages
WHERE id = #{pageId}
  AND diary_id = #{diaryId}
